import{_ as r,l as i,o as e,c as s,v as o,p as l,x as t,d as A,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"ACON 上下文导航","description":"","frontmatter":{"title":"ACON 上下文导航","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/acon-context.md","filePath":"llm/acon-context.md","lastUpdated":1789023840000}'),c={name:"llm/acon-context.md"};function h(d,a,m,B,C,P){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="acon-上下文导航" tabindex="-1">ACON 上下文导航 <a class="header-anchor" href="#acon-上下文导航" aria-label="Permalink to &quot;ACON 上下文导航&quot;">​</a></h1><div class="epigraph"><p>在自然语言空间里迭代改压缩指南：对照「全文成功、压缩失败」的成对轨迹，让指南学会保住环境相关的状态，而不去微调代理权重。</p><footer>—— Kang、Chen、Han 等，ACON: Optimizing Context Compression for Long-horizon LLM Agents，arXiv:2510.00615，ICML 2026</footer></div><p>KAIST / Microsoft 的 Minki Kang、Wei-Ning Chen、Dongge Han 等提出 <strong>ACON</strong>（Agent Context Optimization）。中文里常被说成「上下文导航」，指的是用自然语言指南<strong>引导</strong>压缩器走哪条保留/删除路径，而不是在图上做 GIS 导航。长程代理的观察与历史无界增长，截断或通用摘要会丢掉文件路径、API 参数这类状态。启发式脆，梯度更新又碰不到专有 API 模型。ACON 用失败分析改压缩提示，再把优化后的压缩器蒸馏到小模型。AppWorld、OfficeBench、多目标 QA 上峰值 token 降 26–54%，任务成功不低于压缩基线；小模型作代理可因少分心提升最多约 46%。代码 <code>microsoft/acon</code>。本篇写指南优化与双对象压缩（历史 / 观察）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生产力代理（邮件、办公套件、多应用工作流）必须记住异质信号：事实史、动作—结果、成功前置条件、下一步线索。对话记忆系统优化连贯聊天；文档压缩假设单步用完即可丢。Agent 压缩若只靠「总结得短」，OfficeBench / AppWorld 上会丢路径。MEM1、AgentFold、SUPO 把压缩与策略绑在一起训，不适合只拿得到 GPT API 的部署。</p><p>环境写成 POMDP，历史 \\(h_{t-1}\\) 与最新观察 \\(o_t\\) 条件化出 \\(a_t\\)。上下文代价是峰值 token（决定 KV）与平均长度。压缩器 \\(C\\) 在超过阈值时把历史或观察改写成更短文本，代理权重冻结。目标：在任务奖励不塌的前提下减小峰值。难点是「该留什么」随环境变，手写规则迁不走。</p><h3 id="两种压缩对象" tabindex="-1">两种压缩对象 <a class="header-anchor" href="#两种压缩对象" aria-label="Permalink to &quot;两种压缩对象&quot;">​</a></h3><p><strong>历史压缩</strong>：交互变长时把 \\((o_0,a_0,\\ldots)\\) 收成状态摘要，类似 <a href="/llm/resum-context">ReSum</a> 的重启材料，但指南是优化出来的。<strong>观察压缩</strong>：单次工具返回过长（HTML、邮箱列表）时先压观察再让代理看，类似工具结果清理，但是可学生成式压缩而不是删除。二者阈值独立。论文强调同时覆盖，而先前工作常只做一种。</p><p><span class="marginnote">指南优化属于提示优化家族（Pryzant 等 OPRO/TextGrad 一类思想），监督信号是「压缩后失败而全文成功」的对比，不是人工写的摘要平行语料。没有这对轨迹时，优化器不知道缺了哪条状态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收集训练集轨迹：同一任务跑全文代理与压缩代理。筛选全文成功、压缩失败的配对。优化 LLM 阅读完整 \\(H\\) 与失败的压缩版，指出丢失信息，改写指南 \\(P\\)。迭代直到压缩代理成功率贴近全文，或步数用尽。全程不更新代理参数，故可用 gpt-4.1 一类 API 当代理，压缩器可以是另一模型。</p><p>为降压缩税，用优化后的师生轨迹 LoRA 蒸馏到 Qwen3 / Phi-4 等学生压缩器，文称保留教师准确率 95% 以上。AppWorld 图 1：大模型相对朴素提示压缩，峰值下降且准确率保住；Qwen-14B 作代理时压缩后准确率甚至上升——长上下文分心（Shi 等）被减轻。小模型在 AppWorld / OfficeBench / 多目标 QA 上相对未压缩长历史，分别约 +32% / +20% / +46%（论文贡献条）。</p>',12)),(e(),l(E,null,{default:t(()=>[p(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%85%A8%E6%96%87%E8%BD%A8%E8%BF%B9%EF%BC%9A%E6%88%90%E5%8A%9F%22%5D%20--%3E%20PAIR%5B%22%E9%85%8D%E5%AF%B9%EF%BC%9A%E5%8E%8B%E7%BC%A9%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20COMP%5B%22%E5%8E%8B%E7%BC%A9%E8%BD%A8%E8%BF%B9%EF%BC%9A%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20PAIR%0A%20%20PAIR%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%20LLM%20%E6%94%B9%E5%86%99%E5%8E%8B%E7%BC%A9%E6%8C%87%E5%8D%97%22%5D%0A%20%20OPT%20--%3E%20G%5B%22%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%E6%8C%87%E5%8D%97%20P%22%5D%0A%20%20G%20--%3E%20C%5B%22%E5%8E%8B%E7%BC%A9%E5%99%A8%EF%BC%9A%E5%8E%86%E5%8F%B2%20%2F%20%E8%A7%82%E5%AF%9F%22%5D%0A%20%20C%20--%3E%20A%5B%22%E5%86%BB%E7%BB%93%E7%9A%84%E4%BB%A3%E7%90%86%20LLM%22%5D%0A%20%20G%20--%3E%20DIST%5B%22%E8%92%B8%E9%A6%8F%E5%88%B0%E5%B0%8F%E5%8E%8B%E7%BC%A9%E5%99%A8%22%5D%0A%20%20DIST%20--%3E%20C%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="失败对比是定位器" tabindex="-1">失败对比是定位器 <a class="header-anchor" href="#失败对比是定位器" aria-label="Permalink to &quot;失败对比是定位器&quot;">​</a></h3><p>稀疏的成功/失败不够指导「删哪句」。全文里有而压缩版没有、且与失败动作相关的跨度，才是指南应增加的保留规则（例如「始终保留绝对路径」「保留最后一次 API 错误码」）。环境换了，规则会改：AppWorld 要应用状态，QA 要已搜集的子答案。这就是「导航」：指南在自然语言里指向状态流的关键航点。</p><p>基线含朴素提示压缩、启发式、以及与策略耦合的 RL 压缩。ACON 的卖点是<strong>代理可闭源</strong>。ICML 2026 接收；引用以 arXiv:2510.00615 为准。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>压缩指南是可解释的策略：人可以读 \\(P\\) 做审计，这是相对黑盒 LoRA 压缩器的产品优势。蒸馏之后可解释性部分转移到学生权重，生产若需要审计应保存教师指南版本。观察压缩降低单步峰值；历史压缩降低随时间的峰值。只做一种时，另一侧仍可能顶满。</p><p>小模型受益更大，因为它们更易被长 distractor 打偏。压缩不是免费智能：若指南过猛，关键前置条件丢失，成功率会低于全文。优化目标是贴近全文成功，不是最短摘要。95% 蒸馏保留说明压缩技能可与代理分离，这与 SUPO「摘要即策略」相反。</p><p><span class="marginnote">用户标题里的「导航」不要理解成检索跳转或知识图谱遍历。ACON 不检索外库，只改写已在窗口/观察里的字节。外库记忆见 Mem0 / Zep。</span></p><h3 id="与-resum、supo、acm" tabindex="-1">与 ReSum、SUPO、ACM <a class="header-anchor" href="#与-resum、supo、acm" aria-label="Permalink to &quot;与 ReSum、SUPO、ACM&quot;">​</a></h3><p>ReSum 训策略适应固定摘要工具；ACON 训（优化）压缩指南且代理冻结。SUPO 联合优化工具使用与自评摘要，要开源可训权重。ACM 要代理主动调用卸载工具。闭源办公代理 + 要降 KV：ACON 最贴。要策略学会自己压：SUPO。要原文可回查：ACM。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>配对轨迹假设「全文能成功」——全文也失败的任务给不出对比信号，难题可能欠优化。优化器 LLM 的费用发生在离线阶段，应摊入训练预算。蒸馏学生若比代理还大，峰值收益会被压缩步骤吃回；论文才强调小压缩器。AppWorld / OfficeBench 步数 15+，不是单轮聊天；不要把 26–54% 套到客服闲聊。</p><p><span class="marginnote">出处：Kang, Chen, Han, Inan, Wutschitz, Chen, Sim, Rajmohan，<em>ACON: Optimizing Context Compression for Long-horizon LLM Agents</em>，arXiv:2510.00615，ICML 2026。<a href="https://github.com/microsoft/acon%E3%80%82Microsoft" target="_blank" rel="noreferrer">https://github.com/microsoft/acon。Microsoft</a> Research 出版物页同步。分心现象见 Shi 等 <em>Large Language Models Can Be Easily Distracted</em>。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ACON 用失败对比在自然语言里优化压缩指南，代理权重不动，适合 API 模型。</li><li>同时压历史与观察；峰值 token 降 26–54%，小压缩器可蒸馏到教师约 95%。</li><li>小代理可因去分心提升最多约 46%；「导航」指指南引导保留航点。</li><li>出处：arXiv:2510.00615。</li></ul>',14))])}const g=r(c,[["render",h]]);export{u as __pageData,g as default};
